@import "tailwindcss";

@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Outfit", ui-sans-serif, system-ui, sans-serif;

  /* Brand Color Palette */
  --color-brand-primary: #076c9a; /* Active Blue */
  --color-brand-primary-hover: #0DABA4;
  --color-brand-secondary: #5C4716; /* Brown */
  --color-brand-secondary-hover: #4a3912;
  --color-brand-accent: #82b9cc; /* Soft Blue */
  --color-brand-accent-hover: #6ea3b4;

  --color-brand-bg: #edf8fd; /* Soft Blue Light BG */
  --color-brand-surface: #ffffff;
  --color-brand-text: #1c1917; /* Stone 900 */
  --color-brand-text-muted: #57534e; /* Stone 500 */
  --color-brand-border: #e7e5e4; /* Stone 200 */
}

@layer base {
  :root {
    --app-safe-area-top: env(safe-area-inset-top, 0px);
    --app-safe-area-right: env(safe-area-inset-right, 0px);
    --app-safe-area-bottom: env(safe-area-inset-bottom, 0px);
    --app-safe-area-left: env(safe-area-inset-left, 0px);
  }

  body {
    @apply bg-brand-bg text-brand-text font-sans antialiased selection:bg-brand-accent/30 overflow-x-hidden;
  }

  h1, h2, h3, h4, h5, h6 {
    @apply font-display tracking-tight text-brand-primary;
  }
}

@layer components {
  .btn-primary {
    @apply inline-flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-xl shadow-sm text-white bg-brand-primary hover:bg-brand-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-primary transition-all duration-200 active:scale-95;
  }

  .btn-secondary {
    @apply inline-flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-xl shadow-sm text-white bg-brand-secondary hover:bg-brand-secondary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-secondary transition-all duration-200 active:scale-95;
  }

  .btn-outline {
    @apply inline-flex items-center justify-center px-4 py-2 border border-brand-border text-sm font-medium rounded-xl text-brand-text bg-white hover:bg-brand-bg hover:border-brand-primary/30 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-primary transition-all duration-200 active:scale-95;
  }

  .card {
    @apply bg-white rounded-2xl shadow-sm border border-brand-border overflow-hidden transition-all duration-200 hover:shadow-md;
  }

  .input-field {
    @apply w-full rounded-xl border-brand-border shadow-sm focus:border-brand-primary focus:ring-brand-primary sm:text-sm transition-colors duration-200 bg-white;
  }
}

/* O container Android já aplica esses insets nativamente. Zerar as variáveis
   no WebView evita que a mesma área seja compensada novamente pelo CSS. */
.is-webview {
  --app-safe-area-top: 0px;
  --app-safe-area-right: 0px;
  --app-safe-area-bottom: 0px;
  --app-safe-area-left: 0px;
}

/* A área reservada precisa acompanhar a posição real da bottom navigation. */
.app-main-content {
  padding-bottom: calc(4rem + var(--app-safe-area-bottom));
}

.app-mobile-menu-header {
  padding-top: max(1rem, var(--app-safe-area-top));
  padding-right: max(1rem, var(--app-safe-area-right));
  padding-bottom: 1rem;
  padding-left: max(1rem, var(--app-safe-area-left));
}

.app-mobile-menu-content {
  padding-bottom: calc(6rem + var(--app-safe-area-bottom));
}

.app-mobile-bottom-nav {
  bottom: var(--app-safe-area-bottom);
  padding-top: 0.5rem;
  padding-right: max(0.5rem, var(--app-safe-area-right));
  padding-bottom: 0.5rem;
  padding-left: max(0.5rem, var(--app-safe-area-left));
}

.app-safe-bottom {
  bottom: var(--app-safe-area-bottom);
}

.app-safe-bottom-4 {
  bottom: calc(1rem + var(--app-safe-area-bottom));
}

.app-install-bottom {
  bottom: var(--app-safe-area-bottom);
}

.app-cookie-floating {
  bottom: calc(1rem + var(--app-safe-area-bottom));
}

.app-safe-bottom-padding {
  padding-bottom: calc(1rem + var(--app-safe-area-bottom));
}

.app-floating-bottom {
  bottom: calc(1.5rem + var(--app-safe-area-bottom));
}

.app-floating-bottom-high {
  bottom: calc(6rem + var(--app-safe-area-bottom));
}

@media (min-width: 768px) {
  .app-install-bottom {
    bottom: 1.5rem;
  }
}

@media (min-width: 768px) {
  .app-main-content {
    padding-bottom: 0;
  }
}

/* Compatibilidade com WebView do App: filtros e animações de entrada em
   camadas fixed podem falhar ou congelar a renderização dos modais. */
.is-webview .backdrop-blur-xs,
.is-webview .backdrop-blur-sm,
.is-webview .backdrop-blur-md,
.is-webview .backdrop-blur-lg,
.is-webview .backdrop-blur {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

.is-webview .animate-in,
.is-webview .animate-fade-in,
.is-webview .animate-fadeIn,
.is-webview .animate-scaleIn,
.is-webview .animate-scale-up {
  animation: none !important;
  opacity: 1 !important;
  transform: none !important;
  transition: none !important;
}

/* Alguns WebViews Android não preservam o User-Agent customizado da
   aplicação. Em telas estreitas, mantenha os modais em uma única camada
   estável mesmo quando a detecção acima não estiver disponível. */
@media (max-width: 767px) {
  .backdrop-blur-xs,
  .backdrop-blur-sm,
  .backdrop-blur-md,
  .backdrop-blur-lg,
  .backdrop-blur {
    -webkit-backdrop-filter: none !important;
    backdrop-filter: none !important;
  }

  .animate-in,
  .animate-fade-in,
  .animate-fadeIn,
  .animate-scaleIn,
  .animate-scale-up {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

/* Estilos de Impressão Limpa */
@media print {
  @page {
    margin: 0 !important;
  }

  /* Oculta completamente o root do React e elementos extras para evitar páginas vazias */
  #root, .no-print {
    display: none !important;
  }

  html, body {
    margin: 0 !important;
    padding: 0 !important;
    height: auto !important;
    min-height: 0 !important;
    overflow: visible !important;
    background: white !important;
  }

  #print-area {
    display: block !important;
    visibility: visible !important;
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    width: 100% !important;
    margin: 0 !important;
    padding-top: 20mm !important;
    padding-right: 20mm !important;
    padding-bottom: 20mm !important;
    padding-left: 20mm !important;
    background: white !important;
    color: #1c1917 !important;
    box-sizing: border-box !important;
  }

  #print-area * {
    visibility: visible !important;
  }

  /* Garante que o conteúdo Markdown seja formatado no PDF */
  .print-report-content h1,
  .print-report-content h2,
  .print-report-content h3 {
    visibility: visible !important;
    color: #1c1917 !important;
    font-weight: 700 !important;
  }
}

/* ── Estilo do conteúdo Markdown dos Relatórios ── */
.report-content {
  font-size: 0.875rem;
  line-height: 1.75;
  color: #292524;
}

.report-content h1 {
  font-size: 1.25rem;
  font-weight: 700;
  color: #1d4ed8;
  margin-bottom: 0.5rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid #e0e7ff;
}

.report-content h2 {
  font-size: 1rem;
  font-weight: 700;
  color: #1d4ed8;
  margin-top: 1.25rem;
  margin-bottom: 0.375rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.report-content h3 {
  font-size: 0.9rem;
  font-weight: 600;
  color: #374151;
  margin-top: 1rem;
  margin-bottom: 0.25rem;
}

.report-content p {
  margin-bottom: 0.625rem;
}

.report-content strong {
  font-weight: 700;
  color: #1c1917;
}

.report-content em {
  font-style: italic;
  color: #6b7280;
  font-size: 0.8rem;
}

.report-content ul {
  list-style: none;
  padding-left: 0;
  margin-bottom: 0.75rem;
  space-y: 0.375rem;
}

.report-content ul li {
  position: relative;
  padding-left: 1.25rem;
  margin-bottom: 0.3rem;
}

.report-content ul li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: #4f46e5;
  font-weight: 700;
}

.report-content hr {
  border: none;
  border-top: 1px solid #e5e7eb;
  margin: 1.25rem 0;
}

.report-content blockquote {
  border-left: 3px solid #4f46e5;
  padding-left: 0.75rem;
  color: #6b7280;
  font-style: italic;
  margin: 0.75rem 0;
