import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Activity,
  AlertTriangle,
  ArrowLeft,
  CheckCircle2,
  Clock,
  ExternalLink,
  FileSpreadsheet,
  Loader2,
  MessageSquareText,
  RefreshCw,
  Send,
  ShieldCheck
} from 'lucide-react';
import { supabase } from '../supabaseClient';

