  type ProfessionalFunnelBoardForNotifications,
} from '../utils/notificationRecipients';
import type { ProfessionalFunnelStageKey } from '../../server/admin/professionalFunnel';

const alert = (msg: string) => {
  void showAlert(msg, {
    title: "Aviso",
    variant: "info",
    icon: "info"
  });
};

type AcquisitionInfo = AcquisitionData;

const acquisitionPlatformLabel = (info?: AcquisitionInfo | null) => {
  const platform = getAcquisitionPlatform(info);
  if (platform === 'android') return 'Android';
  if (platform === 'pwa') return 'PWA';
  if (platform === 'web') return 'Web';
  return 'Não informado';
};

const acquisitionDistributionLabel = (info?: AcquisitionInfo | null) => (
  getAcquisitionDistribution(info) === 'google_play' ? 'Google Play' : 'Não informada'
);

const marketingValue = (value?: string) => isTechnicalPlatformMarker(value) ? undefined : value;

const hasAcquisitionInfo = (info?: AcquisitionInfo | null) => Boolean(
  info && (info.channel || info.utm_source || info.referrer || info.landing_page || info.gclid || info.fbclid)
);

interface Professional {
  id: string;
  google_email: string;
  full_name: string;
  photo_url?: string;
  role: 'admin' | 'therapist';
  status: 'active' | 'pending' | 'inactive';
  created_at?: string;
  subscription_plan?: SubscriptionPlan;
  subscription_status?: 'trialing' | 'active' | 'past_due' | 'canceled' | 'unpaid';
  subscription_ends_at?: string;
  trial_ends_at?: string;
  acquisition_info?: AcquisitionInfo;
  signup_acquisition_info?: AcquisitionInfo;
}

type JourneyGroupCheckStatus = 'unknown' | 'checking' | 'member' | 'not_member' | 'missing_phone' | 'indeterminate';

interface JourneyGroupCheckState {
  status: JourneyGroupCheckStatus;
  checkedAt?: string;
  message?: string;
}

interface JourneyGroupBatchProgress {
  completed: number;
  total: number;
}

function ProfessionalAvatar({ professional }: { professional: Professional }) {
  const photoUrl = String(professional.photo_url || '').trim();
  const [source, setSource] = useState(photoUrl);
  const [retryAttempted, setRetryAttempted] = useState(false);
  const [imageFailed, setImageFailed] = useState(!photoUrl);

  useEffect(() => {
    setSource(photoUrl);
    setRetryAttempted(false);
    setImageFailed(!photoUrl);
  }, [photoUrl]);

  const handleImageError = () => {
    if (photoUrl && !retryAttempted) {
      setRetryAttempted(true);
      setSource(addAvatarCacheBuster(photoUrl, Date.now()));
      return;
    }

    setImageFailed(true);
  };

  if (imageFailed) {
    return (
      <div
        role="img"
        aria-label={`Avatar de ${professional.full_name}`}
        title={professional.full_name}
        className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-brand-primary/20 bg-brand-primary/10 text-xs font-bold text-brand-primary"
      >
        {getProfessionalInitials(professional.full_name)}
      </div>
    );
  }

  return (
    <img
      src={source}
      alt={professional.full_name}
      className="h-10 w-10 shrink-0 rounded-full border border-brand-border object-cover"
      referrerPolicy="no-referrer"
      decoding="async"
      onError={handleImageError}
    />
  );
}

