  const handleSendNotification = async (e: React.FormEvent) => {
    e.preventDefault();
    const targets = resolveManualNotificationTargets();
    if (!targets || !(await confirmManualNotificationTargets(targets.length))) return;

    setNotifSending(true);
    setNotifSendSuccess(false);
    setNotifSendError('');
    setNotifWhatsappSummary(null);
    setNotifPushSummary(null);

    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;
      if (!token) throw new Error('Não autenticado.');

      let successCount = 0;
      let errorMsg = '';
      let whatsappAcceptedCount = 0;
      let whatsappSkippedCount = 0;
      let whatsappFailedCount = 0;
      let pushAcceptedCount = 0;

      for (const targetId of targets) {
        try {
          const res = await fetch('/api/notifications/send', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify({
              userId: targetId,
              title: notifTitle,
              content: notifContent,
              type: notifType,
              link: notifLink || undefined,
              imageUrl: notifImageUrl || undefined,
              source: 'manual-push',
              audience: getManualNotificationAudience(),
              channels: { inApp: true, push: true, email: false, whatsapp: false }
          })
        });

          if (res.ok) {
            const resData = await res.json().catch(() => ({}));
            addStoredManualPushNotificationId(resData?.notification?.id);
            if (resData?.push?.accepted === true) pushAcceptedCount++;
            if (notifSendWhatsapp) {
              const whatsappStatus = String(resData?.whatsapp?.status || 'not_sent');
              if (whatsappStatus === 'accepted') whatsappAcceptedCount++;
              else if (whatsappStatus === 'not_sent') whatsappSkippedCount++;
              else whatsappFailedCount++;
            }
            successCount++;
          } else {
            const errData = await res.json().catch(() => ({}));
            errorMsg = errData.error || 'Erro no envio';
          }
        } catch (err: any) {
          errorMsg = err.message;
        }
      }

      if (successCount > 0) {
        setNotifSendSuccess(true);
        setNotifPushSummary(`Push: ${pushAcceptedCount} aceita(s) pelo provedor para ${successCount} destinatário(s). Aceita não significa entregue.`);
        if (notifSendWhatsapp) {
          setNotifWhatsappSummary(`WhatsApp: ${whatsappAcceptedCount} aceita(s) pela Meta, ${whatsappSkippedCount} sem envio e ${whatsappFailedCount} com falha. Aceita não significa entregue.`);
        }
        setNotifTitle('');
        setNotifContent('');
        setNotifLink('');
        setNotifImageUrl('');
        await refreshPushNotificationLogs();
      } else {
        setNotifSendError(errorMsg || 'Falha ao enviar notificações.');
      }
    } catch (err: any) {
      console.error('Erro ao disparar notificações:', err);
      setNotifSendError(err.message || 'Erro inesperado.');
    } finally {
      setNotifSending(false);
    }
  };

