                  <div className="bg-brand-bg/50 p-3 rounded-xl border border-brand-border/30">
                    <span className="text-brand-text-muted block uppercase tracking-wider text-[10px] font-semibold">Valor da Transação</span>
                    <span className="font-bold text-brand-text">
                      {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: selectedTxForReason.currency?.toUpperCase() || 'BRL' }).format(selectedTxForReason.amount)}
                    </span>
                  </div>
                  <div className="bg-brand-bg/50 p-3 rounded-xl border border-brand-border/30">
                    <span className="text-brand-text-muted block uppercase tracking-wider text-[10px] font-semibold">Data da Transação</span>
                    <span className="font-bold text-brand-text">
                      {selectedTxForReason.created_at ? new Date(selectedTxForReason.created_at).toLocaleDateString('pt-BR', {
                        day: '2-digit',
                        month: '2-digit',
                        year: 'numeric',
                        hour: '2-digit',
                        minute: '2-digit'
                      }) : 'N/A'}
                    </span>
                  </div>
                </div>
              </div>

              <div className="pt-4 border-t border-brand-border/60">
                <button
                  type="button"
                  onClick={() => setSelectedTxForReason(null)}
                  className="w-full py-3 bg-brand-primary text-white font-bold rounded-xl text-sm hover:bg-brand-primary-hover transition-colors shadow shadow-brand-primary/20 cursor-pointer text-center block"
                >
                  Fechar Janela
                </button>
              </div>
            </div>
          </div>
        )}

        <ProfessionalDetailsModal
          professional={selectedProfessionalDetails}
          onClose={() => setSelectedProfessionalDetails(null)}
        />

        {/* Modal de Origem e Rastreamento de Aquisição (UTMs) */}
        {selectedAcquisitionProf && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fadeIn">
            <div className="bg-white rounded-3xl max-w-xl w-full shadow-2xl overflow-hidden border border-brand-border/60 animate-in zoom-in-95 duration-200">
              <div className="px-6 py-4 bg-gradient-to-r from-brand-primary/10 via-indigo-500/10 to-brand-accent/10 border-b border-brand-border/50 flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <div className="p-2.5 bg-indigo-600 text-white rounded-xl shadow-md">
                    <Compass className="w-5 h-5" />
                  </div>
                  <div>
                    <h3 className="text-base font-bold text-brand-primary font-display">
                      Origem de Aquisição e UTMs
                    </h3>
                    <p className="text-xs text-brand-text-muted">
                      {selectedAcquisitionProf.full_name} ({selectedAcquisitionProf.google_email})
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => setSelectedAcquisitionProf(null)}
                  className="p-1.5 rounded-lg text-brand-text-muted hover:text-brand-text hover:bg-black/5 transition-colors cursor-pointer"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="p-6 space-y-6 max-h-[80vh] overflow-y-auto">
                {hasAcquisitionInfo(selectedAcquisition) ? (
                  <>
                    {/* Canal em Destaque */}
                    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                      <div className="p-4 bg-indigo-50/70 border border-indigo-100 rounded-2xl flex items-center justify-between shadow-sm">
                        <div>
                          <span className="text-[10px] font-bold uppercase tracking-wider text-indigo-600 block">
                            {selectedAcquisitionIsSignupTouch ? 'Origem no momento do cadastro' : 'Origem disponível (primeiro acesso)'}
                          </span>
                          <span className="text-base font-extrabold text-indigo-950">
                            {selectedAcquisitionChannel}
                          </span>
                        </div>
                        <div className="p-2.5 bg-indigo-600 text-white rounded-xl shadow-sm">
                          <Target className="w-5 h-5" />
                        </div>
                      </div>
                      <div className="p-4 bg-slate-50 border border-slate-200 rounded-2xl">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-indigo-600 block">
                          Primeiro acesso
                        </span>
                        <span className="text-sm font-extrabold text-slate-800">
                          {hasAcquisitionInfo(selectedFirstAcquisition) ? selectedFirstAcquisitionChannel : 'Não registrado'}
                        </span>
                        <p className="mt-1 text-[10px] text-slate-500">
                          O bloco detalhado abaixo prioriza a origem capturada no cadastro.
                        </p>
                      </div>
                    </div>

                    {/* Grid de UTMs */}
                    <div className="space-y-3">
                      <h4 className="text-xs font-bold text-brand-text uppercase tracking-wider flex items-center gap-1.5">
                        <Sparkles className="w-3.5 h-3.5 text-brand-primary" />
                        Parâmetros de Rastreamento (UTMs)
                      </h4>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">UTM Source</span>
                          <p className="font-semibold text-gray-800 break-all">
                            {marketingValue(selectedAcquisition?.utm_source) || <span className="text-gray-400 italic">Não informado</span>}
                          </p>
                        </div>

                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">UTM Medium</span>
                          <p className="font-semibold text-gray-800 break-all">
                            {marketingValue(selectedAcquisition?.utm_medium) || <span className="text-gray-400 italic">Não informado</span>}
                          </p>
                        </div>

                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">UTM Campaign</span>
                          <p className="font-semibold text-gray-800 break-all">
                            {selectedAcquisition?.utm_campaign || <span className="text-gray-400 italic">Não informado</span>}
                          </p>
                        </div>

                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">UTM Term</span>
                          <p className="font-semibold text-gray-800 break-all">
                            {selectedAcquisition?.utm_term || <span className="text-gray-400 italic">Não informado</span>}
                          </p>
                        </div>

                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1 sm:col-span-2">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">UTM Content</span>
                          <p className="font-semibold text-gray-800 break-all">
                            {selectedAcquisition?.utm_content || <span className="text-gray-400 italic">Não informado</span>}
                          </p>
                        </div>

                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">FBCLID</span>
                          <p className="font-semibold text-gray-800">{selectedAcquisition?.fbclid ? 'Capturado' : 'Não capturado'}</p>
                        </div>

                        <div className="p-3 bg-gray-50 rounded-xl border border-gray-100 space-y-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase block">GCLID</span>
                          <p className="font-semibold text-gray-800">{selectedAcquisition?.gclid ? 'Capturado' : 'Não capturado'}</p>
                        </div>
                      </div>
                    </div>

                    {/* Informações Técnicas de Acesso */}
                    <div className="space-y-3 pt-2 border-t border-brand-border/40">
                      <h4 className="text-xs font-bold text-brand-text uppercase tracking-wider flex items-center gap-1.5">
                        <Globe className="w-3.5 h-3.5 text-brand-primary" />
                        Dados de Entrada e Navegação
                      </h4>

                      <div className="space-y-2 text-xs">
                        <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                          <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                            <span className="text-[10px] font-bold text-gray-400 uppercase block">Plataforma de acesso</span>
                            <span className="font-semibold text-gray-700">{acquisitionPlatformLabel(selectedAcquisition)}</span>
                          </div>
                          <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                            <span className="text-[10px] font-bold text-gray-400 uppercase block">Distribuição</span>
                            <span className="font-semibold text-gray-700">{acquisitionDistributionLabel(selectedAcquisition)}</span>
                          </div>
                        </div>
                        {selectedAcquisition?.referrer && (
                          <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 space-y-1">
                            <span className="text-[10px] font-bold text-gray-400 uppercase block">Site de Origem (Referrer)</span>
                            <a
                              href={selectedAcquisition.referrer}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="font-medium text-brand-primary hover:underline break-all flex items-center gap-1"
                            >
                              <span>{selectedAcquisition.referrer}</span>
                              <ExternalLink className="w-3 h-3 flex-shrink-0" />
                            </a>
                          </div>
                        )}

                        {selectedAcquisition?.landing_page && (
                          <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 space-y-1">
                            <span className="text-[10px] font-bold text-gray-400 uppercase block">Página Inicial de Entrada (Landing Page)</span>
                            <p className="font-mono text-[11px] text-gray-700 break-all">
                              {selectedAcquisition.landing_page}
                            </p>
                          </div>
                        )}

                        {selectedAcquisition?.first_seen_at && (
                          <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                            <span className="text-[10px] font-bold text-gray-400 uppercase">Primeiro Acesso Detectado</span>
                            <span className="font-semibold text-gray-700">
                              {new Date(selectedAcquisition.first_seen_at).toLocaleString('pt-BR')}
                            </span>
                          </div>
                        )}

                        {selectedAcquisition?.attribution_method && (
                          <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between gap-3">
                            <span className="text-[10px] font-bold text-gray-400 uppercase">Método de atribuição</span>
                            <span className="font-semibold text-right text-gray-700">
                              {selectedAcquisition.attribution_method === 'google_play_install_referrer'
                                ? 'Google Play Install Referrer'
                                : 'Parâmetros da URL'}
                            </span>
                          </div>
                        )}
                      </div>
                    </div>
                  </>
                ) : (
                  <div className="p-8 text-center space-y-3">
                    <div className="w-12 h-12 bg-gray-100 text-gray-400 rounded-2xl flex items-center justify-center mx-auto">
                      <Compass className="w-6 h-6" />
                    </div>
                    <h4 className="text-sm font-bold text-brand-text">Sem dados de rastreamento (UTMs)</h4>
                    <p className="text-xs text-brand-text-muted max-w-sm mx-auto leading-relaxed">
                      Este usuário não possui parâmetros de UTM ou origem registrados. Isso acontece em contas criadas antes da ativação do rastreamento ou em acessos diretos sem parâmetros de busca na URL.
                    </p>
                  </div>
                )}
              </div>

              <div className="px-6 py-4 bg-gray-50 border-t border-brand-border/40 flex justify-end">
                <button
                  type="button"
                  onClick={() => setSelectedAcquisitionProf(null)}
                  className="btn-primary py-2 px-5 text-xs font-semibold"
                >
                  Fechar
                </button>
              </div>
            </div>
          </div>
        )}
      </main>
      <footer className="p-8 mt-auto opacity-50 text-center">
        <AppVersion />
      </footer>
    </div>
  );
}

